ValidationRule.errorConditionFormula:
AND(ISPICKVAL(   GSC_Sub_Category__c   , "Billing Dispute"),
RecordType_Name__c ="Global Service Case",  
OR(
ISBLANK( GSC_Collections_Account__c ),
ISPICKVAL( GSC_Collections_Segmentation__c,"" )
),
NOT(
AND(
ISPICKVAL(Origin,"Public Community Portal"),
ISPICKVAL(Status,"New")
)
)
)
